    rdfs:comment "Links an InvoiceMessage to a Pivot Organization Role Assignment instance." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Pivot_OrganizationRoleAssignment .

:isRoleAssignmentOf a owl:ObjectProperty ;
    rdfs:label "is role assignment of" ;
    rdfs:comment "Inverse of hasRoleAssignment." ;
    rdfs:domain :Pivot_OrganizationRoleAssignment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasRoleAssignment .

:assignedRole a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "assigned role" ;
    rdfs:comment "Links a Pivot Organization Role Assignment to the AgentRole." ;
    rdfs:domain :Pivot_OrganizationRoleAssignment ;
    rdfs:range :AgentRole .

:isAssignedRoleOf a owl:ObjectProperty ;
    rdfs:label "is assigned role of" ;
    rdfs:comment "Inverse of assignedRole." ;
    rdfs:domain :AgentRole ;
    rdfs:range :Pivot_OrganizationRoleAssignment ;
    owl:inverseOf :assignedRole .

:assignedOrganization a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "assigned organization" ;
    rdfs:comment "Links a Pivot Organization Role Assignment to the Organization." ;
    rdfs:domain :Pivot_OrganizationRoleAssignment ;
    rdfs:range :Organization .

:isAssignedOrganizationOf a owl:ObjectProperty ;
    rdfs:label "is assigned organization of" ;
    rdfs:comment "Inverse of assignedOrganization." ;
    rdfs:domain :Organization ;
    rdfs:range :Pivot_OrganizationRoleAssignment ;
    owl:inverseOf :assignedOrganization .

:hasAddress a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has address" ;
    rdfs:comment "Links an Organization to its Address." ;
    rdfs:domain :Organization ;
    rdfs:range :Address .

:isAddressOf a owl:ObjectProperty ;
    rdfs:label "is address of" ;
    rdfs:comment "Inverse of hasAddress." ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    owl:inverseOf :hasAddress .

:hasItem a owl:ObjectProperty ;
    rdfs:label "has item" ;
    rdfs:comment "Links an InvoiceDetail to its contained Items." ;
    rdfs:domain :InvoiceDetail ;
    rdfs:range :Item .

:isItemOf a owl:ObjectProperty ;
    rdfs:label "is item of" ;
    rdfs:comment "Inverse of hasItem." ;
    rdfs:domain :Item ;
    rdfs:range :InvoiceDetail ;
    owl:inverseOf :hasItem .

:hasPrice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has price" ;
    rdfs:comment "Links an Item to its Price." ;
    rdfs:domain :Item ;
    rdfs:range :Price .

:isPriceOf a owl:ObjectProperty ;
    rdfs:label "is price of" ;
    rdfs:comment "Inverse of hasPrice." ;
    rdfs:domain :Price ;
    rdfs:range :Item ;
    owl:inverseOf :hasPrice .

:hasQuantity a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has quantity" ;
    rdfs:comment "Links an Item to its Quantity." ;
    rdfs:domain :Item ;
    rdfs:range :Quantity .

:isQuantityOf a owl:ObjectProperty ;
    rdfs:label "is quantity of" ;
    rdfs:comment "Inverse of hasQuantity." ;
    rdfs:domain :Quantity ;
    rdfs:range :Item ;
    owl:inverseOf :hasQuantity .

:hasTax a owl:ObjectProperty ;
    rdfs:label "has tax" ;
    rdfs:comment "Links an InvoiceSummary to its Tax information." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :Tax .

:isTaxOf a owl:ObjectProperty ;
    rdfs:label "is tax of" ;
    rdfs:comment "Inverse of hasTax." ;
    rdfs:domain :Tax ;
    rdfs:range :InvoiceSummary ;
    owl:inverseOf :hasTax .

:isAssignedToBusinessProcess a owl:ObjectProperty ;
    rdfs:label "is assigned to business process" ;
    rdfs:comment "Links an InvoiceMessage to a Business Process." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess .

:isBusinessProcessOf a owl:ObjectProperty ;
    rdfs:label "is business process of" ;
    rdfs:comment "Inverse of isAssignedToBusinessProcess." ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :isAssignedToBusinessProcess .

:validatesWithConstraint a owl:ObjectProperty ;
    rdfs:label "validates with constraint" ;
    rdfs:comment "Links an InvoiceMessage to a Validation Constraint." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ValidationConstraint .

:isConstraintFor a owl:ObjectProperty ;
    rdfs:label "is constraint for" ;
    rdfs:comment "Inverse of validatesWithConstraint." ;
    rdfs:domain :ValidationConstraint ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :validatesWithConstraint .

# Segment-level object properties (inverses omitted for brevity, but can be added similarly)
:hasDTMSegment a owl:ObjectProperty ;
    rdfs:label "has DTM segment" ;
    rdfs:comment "Links an InvoiceMessage to a DTM segment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :DTM_Segment .

:hasRFFSegment a owl:ObjectProperty ;
    rdfs:label "has RFF segment" ;
    rdfs:comment "Links an InvoiceMessage to a RFF segment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :RFF_Segment .

:hasCUXSegment a owl:ObjectProperty ;
    rdfs:label "has CUX segment" ;
    rdfs:comment "Links an InvoiceMessage to a CUX segment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :CUX_Segment .

:hasMOASegment a owl:ObjectProperty ;
    rdfs:label "has MOA segment" ;
    rdfs:comment "Links an InvoiceMessage to a MOA segment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :MOA_Segment .

:hasLINSegment a owl:ObjectProperty ;
    rdfs:label "has LIN segment" ;
    rdfs:comment "Links an InvoiceMessage to a LIN segment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :LIN_Segment .

:hasPRISegment a owl:ObjectProperty ;
    rdfs:label "has PRI segment" ;
    rdfs:comment "Links an InvoiceMessage to a PRI segment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :PRI_Segment .

:hasQTYSegment a owl:ObjectProperty ;
    rdfs:label "has QTY segment" ;
    rdfs:comment "Links an InvoiceMessage to a QTY segment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :QTY_Segment .

:hasTAXSegment a owl:ObjectProperty ;
    rdfs:label "has TAX segment" ;
    rdfs:comment "Links an InvoiceMessage to a TAX segment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :TAX_Segment .

:hasALCSegment a owl:ObjectProperty ;
    rdfs:label "has ALC segment" ;
    rdfs:comment "Links an InvoiceMessage to an ALC segment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ALC_Segment .

:hasPACSegment a owl:ObjectProperty ;
    rdfs:label "has PAC segment" ;
    rdfs:comment "Links an InvoiceMessage to a PAC segment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :PAC_Segment .

:hasTDTSegment a owl:ObjectProperty ;
    rdfs:label "has TDT segment" ;
    rdfs:comment "Links an InvoiceMessage to a TDT segment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :TDT_Segment .

:hasDOCSegment a owl:ObjectProperty ;
    rdfs:label "has DOC segment" ;
    rdfs:comment "Links an InvoiceMessage to a DOC segment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :DOC_Segment .

:hasLOCSegment a owl:ObjectProperty ;
    rdfs:label "has LOC segment" ;
    rdfs:comment "Links an InvoiceMessage to a LOC segment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :LOC_Segment .

:hasUNSSegment a owl:ObjectProperty ;
    rdfs:label "has UNS segment" ;
    rdfs:comment "Links an InvoiceMessage to a UNS segment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :UNS_Segment .

:hasPIASegment a owl:ObjectProperty ;
    rdfs:label "has PIA segment" ;
    rdfs:comment "Links an InvoiceMessage to a PIA segment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :PIA_Segment .

:hasFTXSegment a owl:ObjectProperty ;
    rdfs:label "has FTX segment" ;
    rdfs:comment "Links an InvoiceMessage to a FTX segment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :FTX_Segment .

:hasMEASegment a owl:ObjectProperty ;
    rdfs:label "has MEA segment" ;
    rdfs:comment "Links an InvoiceMessage to a MEA segment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :MEA_Segment .

:hasGIRSegment a owl:ObjectProperty ;
    rdfs:label "has GIR segment" ;
    rdfs:comment "Links an InvoiceMessage to a GIR segment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :GIR_Segment .

:hasPATSegment a owl:ObjectProperty ;
    rdfs:label "has PAT segment" ;
    rdfs:comment "Links an InvoiceMessage to a PAT segment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :PAT_Segment .

:hasUNHSegment a owl:ObjectProperty ;
    rdfs:label "has UNH segment" ;
    rdfs:comment "Links an InvoiceMessage to a UNH segment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :UNH_Segment .

:hasUNTSegment a owl:ObjectProperty ;
    rdfs:label "has UNT segment" ;
    rdfs:comment "Links an InvoiceMessage to a UNT segment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :UNT_Segment .

:hasTODSegment a owl:ObjectProperty ;
    rdfs:label "has TOD segment" ;
    rdfs:comment "Links an InvoiceMessage to a TOD segment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :TOD_Segment .

#################################################################
# Data Properties
#################################################################

:hasGlobalLocationNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has global location number" ;
    rdfs:comment "Links an Organization to its Global Location Number (GLN)." ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string .

:invoiceAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "invoice amount" ;
    rdfs:comment "Represents the invoice total amount in the summary section." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range xsd:decimal .

:invoiceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "invoice number" ;
    rdfs:comment "Represents the invoice number in the header section." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range xsd:string .

:documentDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "document date" ;
    rdfs:comment "Represents the document date in the header section." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range xsd:string .

:referenceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "reference number" ;
    rdfs:comment "Represents a reference number in the header section." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range xsd:string .

:mandatoryIdentifier a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "mandatory identifier" ;
    rdfs:comment "Represents a mandatory identifier required by validation constraints." ;
    rdfs:domain :ValidationConstraint ;
    rdfs:range xsd:string .

#################################################################
# Hierarchy, DisjointUnion, DisjointWith
#################################################################

:InvoiceMessage owl:disjointUnionOf (:InvoiceHeader :InvoiceDetail :InvoiceSummary) .
:Segment owl:disjointUnionOf (:BGM_Segment :NAD_Segment :DTM_Segment :RFF_Segment :CUX_Segment :MOA_Segment :LIN_Segment :PRI_Segment :QTY_Segment :TAX_Segment :ALC_Segment :PAC_Segment :TDT_Segment :DOC_Segment :LOC_Segment :UNS_Segment :PIA_Segment :FTX_Segment :MEA_Segment :GIR_Segment :PAT_Segment :UNH_Segment :UNT_Segment :TOD_Segment) .

:Organization owl:disjointWith :Item , :BusinessProcess .
:AgentRole owl:disjointWith :Address , :GlobalLocationNumber .

#################################################################
# General Class Axioms, Restrictions, Equivalences
#################################################################

# Removed recursive equivalentClass for Buyer/Supplier.
:Buyer a owl:Class ;
    rdfs:label "Buyer" ;
    rdfs:comment "A specialized AgentRole for the buyer organization." ;
    rdfs:subClassOf :AgentRole .

:Supplier a owl:Class ;
    rdfs:label "Supplier" ;
    rdfs:comment "A specialized AgentRole for the supplier organization." ;
    rdfs:subClassOf :AgentRole .

#################################################################
# Annotations
#################################################################
# All classes and properties above include rdfs:label and rdfs:comment annotations.
"}

args.owl_content:
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

:EDIFACT_INVOIC_Ontology a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC Ontology" ;
    rdfs:comment "A deeply structured ontology for UN/EDIFACT D96A INVOIC messages, covering all mandatory and recommended segments, roles, and business processes, aligned with EN 16931-1 and P2P-O." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "Top-level envelope for an EDIFACT interchange, containing messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message contained within an Interchange Envelope." .

:InvoiceMessage a owl:Class ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "An INVOIC message representing a global trade transaction." ;
    rdfs:subClassOf :Message .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A generic EDIFACT segment, part of a message." .

# Segment subclasses
:BGM_Segment a owl:Class ;
    rdfs:label "Beginning of Message Segment" ;
    rdfs:comment "Segment identifying the document type and number (BGM)." ;
    rdfs:subClassOf :Segment .
:NAD_Segment a owl:Class ;
    rdfs:label "Name and Address Segment" ;
    rdfs:comment "Segment providing participant (organization) details (NAD)." ;
    rdfs:subClassOf :Segment .
:DTM_Segment a owl:Class ;
    rdfs:label "Date/Time/Period Segment" ;
    rdfs:comment "Segment specifying dates relevant to the invoice (DTM)." ;
    rdfs:subClassOf :Segment .
:RFF_Segment a owl:Class ;
    rdfs:label "Reference Segment" ;
    rdfs:comment "Segment containing reference numbers such as purchase order or invoice reference (RFF)." ;
    rdfs:subClassOf :Segment .
:CUX_Segment a owl:Class ;
    rdfs:label "Currency Segment" ;
    rdfs:comment "Segment specifying currency details (CUX)." ;
    rdfs:subClassOf :Segment .
:MOA_Segment a owl:Class ;
    rdfs:label "Monetary Amount Segment" ;
    rdfs:comment "Segment specifying monetary amounts (MOA)." ;
    rdfs:subClassOf :Segment .
:LIN_Segment a owl:Class ;
    rdfs:label "Line Item Segment" ;
    rdfs:comment "Segment specifying invoice line items (LIN)." ;
    rdfs:subClassOf :Segment .
:PRI_Segment a owl:Class ;
    rdfs:label "Price Segment" ;
    rdfs:comment "Segment specifying price details (PRI)." ;
    rdfs:subClassOf :Segment .
:QTY_Segment a owl:Class ;
    rdfs:label "Quantity Segment" ;
    rdfs:comment "Segment specifying quantity details (QTY)." ;
    rdfs:subClassOf :Segment .
:TAX_Segment a owl:Class ;
    rdfs:label "Tax Segment" ;
    rdfs:comment "Segment specifying tax details (TAX)." ;
    rdfs:subClassOf :Segment .
:ALC_Segment a owl:Class ;
    rdfs:label "Allowance/Charge Segment" ;
    rdfs:comment "Segment specifying allowances or charges (ALC)." ;
    rdfs:subClassOf :Segment .
:PAC_Segment a owl:Class ;
    rdfs:label "Package Segment" ;
    rdfs:comment "Segment specifying packaging details (PAC)." ;
    rdfs:subClassOf :Segment .
:TDT_Segment a owl:Class ;
    rdfs:label "Transport Details Segment" ;
    rdfs:comment "Segment specifying transport details (TDT)." ;
    rdfs:subClassOf :Segment .
:DOC_Segment a owl:Class ;
    rdfs:label "Document Segment" ;
    rdfs:comment "Segment specifying additional document references (DOC)." ;
    rdfs:subClassOf :Segment .
:LOC_Segment a owl:Class ;
    rdfs:label "Location Segment" ;
    rdfs:comment "Segment specifying locations (LOC)." ;
    rdfs:subClassOf :Segment .
:UNS_Segment a owl:Class ;
    rdfs:label "Section Delimiter Segment" ;
    rdfs:comment "Segment delimiting sections of the invoice (UNS)." ;
    rdfs:subClassOf :Segment .
:PIA_Segment a owl:Class ;
    rdfs:label "Additional Product ID Segment" ;
    rdfs:comment "Segment specifying additional product identifiers (PIA)." ;
    rdfs:subClassOf :Segment .
:FTX_Segment a owl:Class ;
    rdfs:label "Free Text Segment" ;
    rdfs:comment "Segment specifying free text notes (FTX)." ;
    rdfs:subClassOf :Segment .
:MEA_Segment a owl:Class ;
    rdfs:label "Measurements Segment" ;
    rdfs:comment "Segment specifying measurements (MEA)." ;
    rdfs:subClassOf :Segment .
:GIR_Segment a owl:Class ;
    rdfs:label "Related Identification Numbers Segment" ;
    rdfs:comment "Segment specifying related identification numbers (GIR)." ;
    rdfs:subClassOf :Segment .
:PAT_Segment a owl:Class ;
    rdfs:label "Payment Terms Segment" ;
    rdfs:comment "Segment specifying payment terms (PAT)." ;
    rdfs:subClassOf :Segment .
:UNH_Segment a owl:Class ;
    rdfs:label "Message Header Segment" ;
    rdfs:comment "Segment specifying message header details (UNH)." ;
    rdfs:subClassOf :Segment .
:UNT_Segment a owl:Class ;
    rdfs:label "Message Trailer Segment" ;
    rdfs:comment "Segment specifying message trailer details (UNT)." ;
    rdfs:subClassOf :Segment .
:TOD_Segment a owl:Class ;
    rdfs:label "Terms of Delivery Segment" ;
    rdfs:comment "Segment specifying terms of delivery (TOD)." ;
    rdfs:subClassOf :Segment .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite data element." .

:InvoiceHeader a owl:Class ;
    rdfs:label "Invoice Header" ;
    rdfs:comment "Header section of an invoice message." ;
    rdfs:subClassOf :InvoiceMessage .

:InvoiceDetail a owl:Class ;
    rdfs:label "Invoice Detail" ;
    rdfs:comment "Detail section of an invoice message." ;
    rdfs:subClassOf :InvoiceMessage .

:InvoiceSummary a owl:Class ;
    rdfs:label "Invoice Summary" ;
    rdfs:comment "Summary section of an invoice message." ;
    rdfs:subClassOf :InvoiceMessage .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An organization involved in the invoice." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the invoice context (e.g., Buyer, Supplier, Delivery Party)." .

:Pivot_OrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment Pivot" ;
    rdfs:comment "A reification class linking an Organization, its Agent Role, and the InvoiceMessage context." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A physical address associated with an organization." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A unique identifier for organization locations (GLN)." ;
    rdfs:subClassOf :SimpleDataElement .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "An item listed in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "Net price of an item in the invoice." .

:Quantity a owl:Class ;
    rdfs:label "Quantity" ;
    rdfs:comment "Quantity of an item in the invoice." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "Tax information for the invoice." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice is assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "Constraint for automated validation of the invoice (e.g., SHACL, mandatory identifiers)." .

#################################################################
# Object Properties
#################################################################

:containsMessage a owl:ObjectProperty ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an Interchange Envelope to its contained Messages." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message .

:containedInEnvelope a owl:ObjectProperty ;
    rdfs:label "contained in envelope" ;
    rdfs:comment "Inverse of containsMessage; links a Message to its InterchangeEnvelope." ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    owl:inverseOf :containsMessage .

:hasSegment a owl:ObjectProperty ;
    rdfs:label "has segment" ;
    rdfs:comment "Links a Message to its constituent Segments." ;
    rdfs:domain :Message ;
    rdfs:range :Segment .

:isSegmentOf a owl:ObjectProperty ;
    rdfs:label "is segment of" ;
    rdfs:comment "Inverse of hasSegment; links a Segment to its parent Message." ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    owl:inverseOf :hasSegment .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:label "has composite element" ;
    rdfs:comment "Links a Segment to its Composite Data Elements." ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement .

:isCompositeElementOf a owl:ObjectProperty ;
    rdfs:label "is composite element of" ;
    rdfs:comment "Inverse of hasCompositeElement." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment ;
    owl:inverseOf :hasCompositeElement .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:label "has simple element" ;
    rdfs:comment "Links a Composite Data Element to its Simple Data Elements." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement .

:isSimpleElementOf a owl:ObjectProperty ;
    rdfs:label "is simple element of" ;
    rdfs:comment "Inverse of hasSimpleElement." ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement ;
    owl:inverseOf :hasSimpleElement .

:hasHeader a owl:ObjectProperty ;
    rdfs:label "has header" ;
    rdfs:comment "Links an InvoiceMessage to its header section." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceHeader ;
    a owl:FunctionalProperty .

:isHeaderOf a owl:ObjectProperty ;
    rdfs:label "is header of" ;
    rdfs:comment "Inverse of hasHeader." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasHeader .

:hasDetail a owl:ObjectProperty ;
    rdfs:label "has detail" ;
    rdfs:comment "Links an InvoiceMessage to its detail section." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceDetail ;
    a owl:FunctionalProperty .

:isDetailOf a owl:ObjectProperty ;
    rdfs:label "is detail of" ;
    rdfs:comment "Inverse of hasDetail." ;
    rdfs:domain :InvoiceDetail ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasDetail .

:hasSummary a owl:ObjectProperty ;
    rdfs:label "has summary" ;
    rdfs:comment "Links an InvoiceMessage to its summary section." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceSummary ;
    a owl:FunctionalProperty .

:isSummaryOf a owl:ObjectProperty ;
    rdfs:label "is summary of" ;
    rdfs:comment "Inverse of hasSummary." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasSummary .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:label "involves organization" ;
    rdfs:comment "Links an InvoiceMessage to Organizations involved." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Organization .

:isOrganizationInvolvedIn a owl:ObjectProperty ;
    rdfs:label "is organization involved in" ;
    rdfs:comment "Inverse of involvesOrganization." ;
    rdfs:domain :Organization ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :involvesOrganization .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Links an InvoiceMessage to a Pivot Organization Role Assignment instance." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Pivot_OrganizationRoleAssignment .

:isRoleAssignmentOf a owl:ObjectProperty ;
    rdfs:label "is role assignment of" ;
    rdfs:comment "Inverse of hasRoleAssignment." ;
    rdfs:domain :Pivot_OrganizationRoleAssignment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasRoleAssignment .

:assignedRole a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "assigned role" ;
    rdfs:comment "Links a Pivot Organization Role Assignment to the AgentRole." ;
    rdfs:domain :Pivot_OrganizationRoleAssignment ;
    rdfs:range :AgentRole .

:isAssignedRoleOf a owl:ObjectProperty ;
    rdfs:label "is assigned role of" ;
    rdfs:comment "Inverse of assignedRole." ;
    rdfs:domain :AgentRole ;
    rdfs:range :Pivot_OrganizationRoleAssignment ;
    owl:inverseOf :assignedRole .

:assignedOrganization a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "assigned organization" ;
