:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:label "hasRoleAssignment" ;
    rdfs:comment "Links an InvoiceMessage to a PivotOrganizationRoleAssignment instance." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :PivotOrganizationRoleAssignment ;
