#################################################################

:InvoiceMessage owl:disjointUnionOf (:InvoiceHeader :InvoiceDetail :InvoiceSummary) .
:Segment owl:disjointUnionOf (:BGM_Segment :NAD_Segment :DTM_Segment :RFF_Segment :CUX_Segment :MOA_Segment :LIN_Segment :PRI_Segment :QTY_Segment :TAX_Segment :ALC_Segment :PAC_Segment :TDT_Segment :DOC_Segment :LOC_Segment :UNS_Segment :PIA_Segment :FTX_Segment :MEA_Segment :GIR_Segment :PAT_Segment :UNH_Segment :UNT_Segment :TOD_Segment) .

:Organization owl:disjointWith :Item , :BusinessProcess .
:AgentRole owl:disjointWith :Address , :GlobalLocationNumber .

