{"owl_content": "@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

:EDIFACT_INVOIC_Ontology a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC Ontology" ;
    rdfs:comment "A deeply structured ontology for UN/EDIFACT D96A INVOIC messages, covering all mandatory and recommended segments, roles, and business processes, aligned with EN 16931-1 and P2P-O." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "Top-level envelope for an EDIFACT interchange, containing messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message contained within an Interchange Envelope." .

:InvoiceMessage a owl:Class ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "An INVOIC message representing a global trade transaction." ;
    rdfs:subClassOf :Message .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A generic EDIFACT segment, part of a message." .

# Segment subclasses
:BGM_Segment a owl:Class ;
    rdfs:label "BeginningOfMessageSegment" ;
    rdfs:comment "Segment identifying the document type and number (BGM)." ;
    rdfs:subClassOf :Segment .
:NAD_Segment a owl:Class ;
    rdfs:label "NameAndAddressSegment" ;
    rdfs:comment "Segment providing participant (organization) details (NAD)." ;
    rdfs:subClassOf :Segment .
:DTM_Segment a owl:Class ;
    rdfs:label "DateTimePeriodSegment" ;
    rdfs:comment "Segment specifying dates relevant to the invoice (DTM)." ;
    rdfs:subClassOf :Segment .
:RFF_Segment a owl:Class ;
    rdfs:label "ReferenceSegment" ;
    rdfs:comment "Segment containing reference numbers such as purchase order or invoice reference (RFF)." ;
    rdfs:subClassOf :Segment .
:CUX_Segment a owl:Class ;
    rdfs:label "CurrencySegment" ;
    rdfs:comment "Segment specifying currency details (CUX)." ;
    rdfs:subClassOf :Segment .
:MOA_Segment a owl:Class ;
    rdfs:label "MonetaryAmountSegment" ;
    rdfs:comment "Segment specifying monetary amounts (MOA)." ;
    rdfs:subClassOf :Segment .
:LIN_Segment a owl:Class ;
    rdfs:label "LineItemSegment" ;
    rdfs:comment "Segment specifying invoice line items (LIN)." ;
    rdfs:subClassOf :Segment .
:PRI_Segment a owl:Class ;
    rdfs:label "PriceSegment" ;
    rdfs:comment "Segment specifying price details (PRI)." ;
    rdfs:subClassOf :Segment .
:QTY_Segment a owl:Class ;
    rdfs:label "QuantitySegment" ;
    rdfs:comment "Segment specifying quantity details (QTY)." ;
    rdfs:subClassOf :Segment .
:TAX_Segment a owl:Class ;
    rdfs:label "TaxSegment" ;
    rdfs:comment "Segment specifying tax details (TAX)." ;
    rdfs:subClassOf :Segment .
:ALC_Segment a owl:Class ;
    rdfs:label "AllowanceOrChargeSegment" ;
    rdfs:comment "Segment specifying allowances or charges (ALC)." ;
    rdfs:subClassOf :Segment .
:PAC_Segment a owl:Class ;
    rdfs:label "PackageSegment" ;
    rdfs:comment "Segment specifying packaging details (PAC)." ;
    rdfs:subClassOf :Segment .
:TDT_Segment a owl:Class ;
    rdfs:label "TransportDetailsSegment" ;
    rdfs:comment "Segment specifying transport details (TDT)." ;
    rdfs:subClassOf :Segment .
:DOC_Segment a owl:Class ;
    rdfs:label "DocumentSegment" ;
    rdfs:comment "Segment specifying additional document references (DOC)." ;
    rdfs:subClassOf :Segment .
:LOC_Segment a owl:Class ;
    rdfs:label "LocationSegment" ;
    rdfs:comment "Segment specifying locations (LOC)." ;
    rdfs:subClassOf :Segment .
:UNS_Segment a owl:Class ;
    rdfs:label "SectionDelimiterSegment" ;
    rdfs:comment "Segment delimiting sections of the invoice (UNS)." ;
    rdfs:subClassOf :Segment .
:PIA_Segment a owl:Class ;
    rdfs:label "AdditionalProductIDSegment" ;
    rdfs:comment "Segment specifying additional product identifiers (PIA)." ;
    rdfs:subClassOf :Segment .
:FTX_Segment a owl:Class ;
    rdfs:label "FreeTextSegment" ;
    rdfs:comment "Segment specifying free text notes (FTX)." ;
    rdfs:subClassOf :Segment .
:MEA_Segment a owl:Class ;
    rdfs:label "MeasurementsSegment" ;
    rdfs:comment "Segment specifying measurements (MEA)." ;
    rdfs:subClassOf :Segment .
:GIR_Segment a owl:Class ;
    rdfs:label "RelatedIdentificationNumbersSegment" ;
    rdfs:comment "Segment specifying related identification numbers (GIR)." ;
    rdfs:subClassOf :Segment .
:PAT_Segment a owl:Class ;
    rdfs:label "PaymentTermsSegment" ;
    rdfs:comment "Segment specifying payment terms (PAT)." ;
    rdfs:subClassOf :Segment .
:UNH_Segment a owl:Class ;
    rdfs:label "MessageHeaderSegment" ;
    rdfs:comment "Segment specifying message header details (UNH)." ;
    rdfs:subClassOf :Segment .
:UNT_Segment a owl:Class ;
    rdfs:label "MessageTrailerSegment" ;
    rdfs:comment "Segment specifying message trailer details (UNT)." ;
    rdfs:subClassOf :Segment .
:TOD_Segment a owl:Class ;
    rdfs:label "TermsOfDeliverySegment" ;
    rdfs:comment "Segment specifying terms of delivery (TOD)." ;
    rdfs:subClassOf :Segment .

:CompositeDataElement a owl:Class ;
    rdfs:label "CompositeDataElement" ;
    rdfs:comment "A composite data element within a segment." .

:SimpleDataElement a owl:Class ;
    rdfs:label "SimpleDataElement" ;
    rdfs:comment "A simple data element within a composite data element." .

:InvoiceHeader a owl:Class ;
    rdfs:label "InvoiceHeader" ;
    rdfs:comment "Header section of an invoice message." ;
    rdfs:subClassOf :InvoiceMessage .

:InvoiceDetail a owl:Class ;
    rdfs:label "InvoiceDetail" ;
    rdfs:comment "Detail section of an invoice message." ;
    rdfs:subClassOf :InvoiceMessage .

:InvoiceSummary a owl:Class ;
    rdfs:label "InvoiceSummary" ;
    rdfs:comment "Summary section of an invoice message." ;
    rdfs:subClassOf :InvoiceMessage .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An organization involved in the invoice." .

:AgentRole a owl:Class ;
    rdfs:label "AgentRole" ;
    rdfs:comment "A role played by an organization in the invoice context (e.g., Buyer, Supplier, Delivery Party)." .

:PivotOrganizationRoleAssignment a owl:Class ;
    rdfs:label "PivotOrganizationRoleAssignment" ;
    rdfs:comment "A reification class linking an Organization, its Agent Role, and the InvoiceMessage context." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A physical address associated with an organization." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "GlobalLocationNumber" ;
    rdfs:comment "A unique identifier for organization locations (GLN); subclass of SimpleDataElement." ;
    rdfs:subClassOf :SimpleDataElement .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "An item listed in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "Net price of an item in the invoice." .

:Quantity a owl:Class ;
    rdfs:label "Quantity" ;
    rdfs:comment "Quantity of an item in the invoice." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "Tax information for the invoice." .

:BusinessProcess a owl:Class ;
    rdfs:label "BusinessProcess" ;
    rdfs:comment "A business process to which the invoice is assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "ValidationConstraint" ;
    rdfs:comment "Constraint for automated validation of the invoice (e.g., SHACL, mandatory identifiers)." .

#################################################################
# Object Properties (with inverses and improved annotations)
#################################################################

:containsMessage a owl:ObjectProperty ;
    rdfs:label "containsMessage" ;
    rdfs:comment "Links an InterchangeEnvelope to its contained Messages." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    owl:inverseOf :containedInEnvelope .

:containedInEnvelope a owl:ObjectProperty ;
    rdfs:label "containedInEnvelope" ;
    rdfs:comment "Inverse of containsMessage; links a Message to its InterchangeEnvelope." ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    owl:inverseOf :containsMessage .

:hasSegment a owl:ObjectProperty ;
    rdfs:label "hasSegment" ;
    rdfs:comment "Links a Message to its constituent Segments." ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    owl:inverseOf :isSegmentOf .

:isSegmentOf a owl:ObjectProperty ;
    rdfs:label "isSegmentOf" ;
    rdfs:comment "Inverse of hasSegment; links a Segment to its parent Message." ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    owl:inverseOf :hasSegment .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:label "hasCompositeElement" ;
    rdfs:comment "Links a Segment to its CompositeDataElements." ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement ;
    owl:inverseOf :isCompositeElementOf .

:isCompositeElementOf a owl:ObjectProperty ;
    rdfs:label "isCompositeElementOf" ;
    rdfs:comment "Inverse of hasCompositeElement." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment ;
    owl:inverseOf :hasCompositeElement .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:label "hasSimpleElement" ;
    rdfs:comment "Links a CompositeDataElement to its SimpleDataElements." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    owl:inverseOf :isSimpleElementOf .

:isSimpleElementOf a owl:ObjectProperty ;
    rdfs:label "isSimpleElementOf" ;
    rdfs:comment "Inverse of hasSimpleElement." ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement ;
    owl:inverseOf :hasSimpleElement .

:hasHeader a owl:ObjectProperty ;
    rdfs:label "hasHeader" ;
    rdfs:comment "Links an InvoiceMessage to its header section." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceHeader ;
    a owl:FunctionalProperty ;
    owl:inverseOf :isHeaderOf .

:isHeaderOf a owl:ObjectProperty ;
    rdfs:label "isHeaderOf" ;
    rdfs:comment "Inverse of hasHeader." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasHeader .

:hasDetail a owl:ObjectProperty ;
    rdfs:label "hasDetail" ;
