@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

:EDIFACTOntology rdf:type owl:Ontology ;
  rdfs:label "EDIFACT D96A INVOIC Ontology" ;
  rdfs:comment "Ontology for modeling UN/EDIFACT D96A invoice messages, roles, segments, and compliance requirements." .

### Classes
:InterchangeEnvelope rdf:type owl:Class ;
  rdfs:label "Interchange Envelope" ;
  rdfs:comment "Top-level envelope containing EDIFACT messages." .

:Message rdf:type owl:Class ;
  rdfs:label "Message" ;
  rdfs:comment "A generic EDIFACT message." .

:InvoiceMessage rdf:type owl:Class ;
  rdfs:label "Invoice Message" ;
  rdfs:comment "An INVOIC message representing a business invoice." ;
  rdfs:subClassOf :Message .

:Segment rdf:type owl:Class ;
  rdfs:label "Segment" ;
  rdfs:comment "A segment within an EDIFACT message." .

:BGMSegment rdf:type owl:Class ;
  rdfs:label "BGM Segment" ;
  rdfs:comment "Beginning of Message segment for document identification." ;
  rdfs:subClassOf :Segment .

:NADSegment rdf:type owl:Class ;
  rdfs:label "NAD Segment" ;
  rdfs:comment "Name and Address segment for participant details." ;
  rdfs:subClassOf :Segment .

:CompositeDataElement rdf:type owl:Class ;
  rdfs:label "Composite Data Element" ;
  rdfs:comment "Composite element within a segment." .

:SimpleDataElement rdf:type owl:Class ;
  rdfs:label "Simple Data Element" ;
  rdfs:comment "Simple element within a composite or segment." .

:HeaderSection rdf:type owl:Class ;
  rdfs:label "Header Section" ;
  rdfs:comment "Header section of an invoice message, containing dates and reference numbers." ;
  rdfs:subClassOf :Segment .

:DetailSection rdf:type owl:Class ;
  rdfs:label "Detail Section" ;
  rdfs:comment "Detail section listing line items." ;
  rdfs:subClassOf :Segment .

:SummarySection rdf:type owl:Class ;
  rdfs:label "Summary Section" ;
  rdfs:comment "Summary section containing totals and tax." ;
  rdfs:subClassOf :Segment .

:Organization rdf:type owl:Class ;
  rdfs:label "Organization" ;
  rdfs:comment "An organization involved in the invoice (buyer, supplier, delivery party, etc.)." ;
  rdfs:subClassOf :P2POEntity .

:AgentRole rdf:type owl:Class ;
  rdfs:label "Agent Role" ;
  rdfs:comment "Role played by an organization in a transaction (Buyer, Supplier, Delivery Party, etc.)." .

:RoleAssignment rdf:type owl:Class ;
  rdfs:label "Role Assignment" ;
  rdfs:comment "Pivot class linking organizations to roles in a specific invoice context." .

:Address rdf:type owl:Class ;
  rdfs:label "Address" ;
  rdfs:comment "Address of an organization (headquarters, warehouse, etc.)." ;
  rdfs:subClassOf :P2POEntity .

:Item rdf:type owl:Class ;
  rdfs:label "Item" ;
  rdfs:comment "An item sold in the invoice." ;
  rdfs:subClassOf :P2POEntity .

:LineItem rdf:type owl:Class ;
  rdfs:label "Line Item" ;
  rdfs:comment "A line item in the invoice, linking item, price, and quantity." .

:Price rdf:type owl:Class ;
  rdfs:label "Price" ;
  rdfs:comment "Price of an item." ;
  rdfs:subClassOf :P2POEntity .

:Tax rdf:type owl:Class ;
  rdfs:label "Tax" ;
  rdfs:comment "Tax information in the summary section." ;
  rdfs:subClassOf :P2POEntity .

:ReferenceNumber rdf:type owl:Class ;
  rdfs:label "Reference Number" ;
  rdfs:comment "Reference number for document identification." .

:BusinessProcess rdf:type owl:Class ;
  rdfs:label "Business Process" ;
  rdfs:comment "Business process to which the invoice is assigned." .

:Identifier rdf:type owl:Class ;
  rdfs:label "Identifier" ;
  rdfs:comment "Generic identifier class." .

:GLNIdentifier rdf:type owl:Class ;
  rdfs:label "GLN Identifier" ;
  rdfs:comment "Global Location Number identifier for organizations." ;
  rdfs:subClassOf :Identifier .

:EN16931Compliance rdf:type owl:Class ;
  rdfs:label "EN 16931 Compliance" ;
  rdfs:comment "Compliance class for European Standard EN 16931-1." .

:P2POEntity rdf:type owl:Class ;
  rdfs:label "P2P-O Entity" ;
  rdfs:comment "Entity defined in the Purchase-to-Pay Ontology." .

:SHACLConstraint rdf:type owl:Class ;
  rdfs:label "SHACL Constraint" ;
  rdfs:comment "Constraint used for automated validation of invoice data." .

### Disjointness
:Organization owl:disjointWith :Item .
:Price owl:disjointWith :Tax .
:Address owl:disjointWith :Item .
:Message owl:disjointWith :Segment .
:CompositeDataElement owl:disjointWith :SimpleDataElement .

### Properties
:containsMessage rdf:type owl:ObjectProperty ;
  rdfs:label "contains message" ;
  rdfs:comment "Links InterchangeEnvelope to contained Messages." ;
  rdfs:domain :InterchangeEnvelope ;
  rdfs:range :Message ;
  owl:FunctionalProperty .

:hasSegment rdf:type owl:ObjectProperty ;
  rdfs:label "has segment" ;
  rdfs:comment "Links Message to its Segments." ;
  rdfs:domain :Message ;
  rdfs:range :Segment .

:hasHeaderSection rdf:type owl:ObjectProperty ;
  rdfs:label "has header section" ;
  rdfs:comment "Links InvoiceMessage to its HeaderSection." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :HeaderSection ;
  owl:FunctionalProperty .

:hasDetailSection rdf:type owl:ObjectProperty ;
  rdfs:label "has detail section" ;
  rdfs:comment "Links InvoiceMessage to its DetailSection." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :DetailSection ;
  owl:FunctionalProperty .

:hasSummarySection rdf:type owl:ObjectProperty ;
  rdfs:label "has summary section" ;
  rdfs:comment "Links InvoiceMessage to its SummarySection." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :SummarySection ;
  owl:FunctionalProperty .

:hasLineItem rdf:type owl:ObjectProperty ;
  rdfs:label "has line item" ;
  rdfs:comment "Links DetailSection to its LineItems." ;
  rdfs:domain :DetailSection ;
  rdfs:range :LineItem .

:hasRoleAssignment rdf:type owl:ObjectProperty ;
  rdfs:label "has role assignment" ;
  rdfs:comment "Links InvoiceMessage to RoleAssignment pivot class." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :RoleAssignment .

:assignsRole rdf:type owl:ObjectProperty ;
  rdfs:label "assigns role" ;
  rdfs:comment "Links RoleAssignment to AgentRole." ;
  rdfs:domain :RoleAssignment ;
  rdfs:range :AgentRole ;
  owl:FunctionalProperty .

:assignedTo rdf:type owl:ObjectProperty ;
  rdfs:label "assigned to" ;
  rdfs:comment "Links RoleAssignment to Organization." ;
  rdfs:domain :RoleAssignment ;
  rdfs:range :Organization ;
  owl:FunctionalProperty .

:hasAddress rdf:type owl:ObjectProperty ;
  rdfs:label "has address" ;
  rdfs:comment "Links Organization to its Address." ;
  rdfs:domain :Organization ;
  rdfs:range :Address .

:hasGLNIdentifier rdf:type owl:ObjectProperty ;
  rdfs:label "has GLN identifier" ;
  rdfs:comment "Links Organization to its GLNIdentifier." ;
  rdfs:domain :Organization ;
  rdfs:range :GLNIdentifier ;
  owl:FunctionalProperty .

:hasReferenceNumber rdf:type owl:ObjectProperty ;
  rdfs:label "has reference number" ;
  rdfs:comment "Links InvoiceMessage to ReferenceNumber." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :ReferenceNumber ;
  owl:FunctionalProperty .

:hasTax rdf:type owl:ObjectProperty ;
  rdfs:label "has tax" ;
  rdfs:comment "Links SummarySection to Tax." ;
  rdfs:domain :SummarySection ;
  rdfs:range :Tax .

:hasInvoiceAmount rdf:type owl:DatatypeProperty ;
  rdfs:label "has invoice amount" ;
  rdfs:comment "Links SummarySection to the invoice amount." ;
  rdfs:domain :SummarySection ;
  rdfs:range xsd:decimal ;
  owl:FunctionalProperty .

:hasInvoiceNumber rdf:type owl:DatatypeProperty ;
  rdfs:label "has invoice number" ;
  rdfs:comment "Links InvoiceMessage to its invoice number." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range xsd:string ;
  owl:FunctionalProperty .

:hasDate rdf:type owl:DatatypeProperty ;
  rdfs:label "has date" ;
  rdfs:comment "Links HeaderSection to relevant dates." ;
  rdfs:domain :HeaderSection ;
  rdfs:range xsd:string .

:hasNetPrice rdf:type owl:DatatypeProperty ;
  rdfs:label "has net price" ;
  rdfs:comment "Links LineItem to net price." ;
  rdfs:domain :LineItem ;
  rdfs:range xsd:decimal ;
  owl:FunctionalProperty .

:hasQuantity rdf:type owl:DatatypeProperty ;
  rdfs:label "has quantity" ;
  rdfs:comment "Links LineItem to item quantity." ;
  rdfs:domain :LineItem ;
  rdfs:range xsd:decimal .

:compliesWithEN16931 rdf:type owl:ObjectProperty ;
  rdfs:label "complies with EN 16931" ;
  rdfs:comment "Links InvoiceMessage to EN16931Compliance." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :EN16931Compliance ;
  owl:FunctionalProperty .

:validatedBySHACL rdf:type owl:ObjectProperty ;
  rdfs:label "validated by SHACL" ;
  rdfs:comment "Links InvoiceMessage to SHACLConstraint for validation." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :SHACLConstraint .

:assignedToBusinessProcess rdf:type owl:ObjectProperty ;
  rdfs:label "assigned to business process" ;
  rdfs:comment "Links InvoiceMessage to BusinessProcess." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :BusinessProcess ;
  owl:FunctionalProperty .

:hasItem rdf:type owl:ObjectProperty ;
  rdfs:label "has item" ;
  rdfs:comment "Links LineItem to Item." ;
  rdfs:domain :LineItem ;
  rdfs:range :Item ;
  owl:FunctionalProperty .

### Property Characteristics
:containsMessage rdf:type owl:FunctionalProperty .
:hasHeaderSection rdf:type owl:FunctionalProperty .
:hasDetailSection rdf:type owl:FunctionalProperty .
:hasSummarySection rdf:type owl:FunctionalProperty .
:assignsRole rdf:type owl:FunctionalProperty .
:assignedTo rdf:type owl:FunctionalProperty .
:hasGLNIdentifier rdf:type owl:FunctionalProperty .
:hasReferenceNumber rdf:type owl:FunctionalProperty .
:hasInvoiceAmount rdf:type owl:FunctionalProperty .
:hasInvoiceNumber rdf:type owl:FunctionalProperty .
:hasNetPrice rdf:type owl:FunctionalProperty .
:hasItem rdf:type owl:FunctionalProperty .
:compliesWithEN16931 rdf:type owl:FunctionalProperty .
:assignedToBusinessProcess rdf:type owl:FunctionalProperty .

### Restrictions
:BuyerRoleAssignment rdf:type owl:Class ;
  rdfs:label "Buyer Role Assignment" ;
  rdfs:comment "RoleAssignment where AgentRole is Buyer." ;
  owl:equivalentClass [ rdf:type owl:Restriction ; owl:onProperty :assignsRole ; owl:allValuesFrom :AgentRole ] .

:OrganizationWithGLN rdf:type owl:Class ;
  rdfs:label "Organization with GLN" ;
  rdfs:comment "Organization with a GLN identifier." ;
  owl:equivalentClass [ rdf:type owl:Restriction ; owl:onProperty :hasGLNIdentifier ; owl:someValuesFrom :GLNIdentifier ] .

### General Class Axioms
[ rdf:type owl:Restriction ; owl:onProperty :hasRoleAssignment ; owl:someValuesFrom :RoleAssignment ; rdfs:subClassOf :InvoiceMessage ] .
[ rdf:type owl:Restriction ; owl:onProperty :hasSegment ; owl:someValuesFrom :Segment ; rdfs:subClassOf :Message ] .

