  rdfs:comment "An organization involved in the invoice (buyer, supplier, delivery party, etc.)." ;
  rdfs:subClassOf :P2POEntity .

:AgentRole rdf:type owl:Class ;
  rdfs:label "Agent Role" ;
  rdfs:comment "Role played by an organization in a transaction (Buyer, Supplier, Delivery Party, etc.)." .

:RoleAssignment rdf:type owl:Class ;
  rdfs:label "Role Assignment" ;
  rdfs:comment "Pivot class linking organizations to roles in a specific invoice context." .

:Address rdf:type owl:Class ;
