  rdfs:comment "Compliance class for European Standard EN 16931-1." .

:P2POEntity rdf:type owl:Class ;
  rdfs:label "P2P-O Entity" ;
  rdfs:comment "Entity defined in the Purchase-to-Pay Ontology." .

:SHACLConstraint rdf:type owl:Class ;
  rdfs:label "SHACL Constraint" ;
  rdfs:comment "Constraint used for automated validation of invoice data." .

