  rdfs:domain :InvoiceMessage ;
  rdfs:range :RoleAssignment .
:hasRoleAssignment owl:inverseOf :isRoleAssignmentOf .
:isRoleAssignmentOf rdf:type owl:ObjectProperty ;
  rdfs:label "is role assignment of" ;
  rdfs:comment "Links RoleAssignment to InvoiceMessage as the context for the assignment." ;
  rdfs:domain :RoleAssignment ;
  rdfs:range :InvoiceMessage .

:assignsRole rdf:type owl:ObjectProperty ;
  rdfs:label "assigns role" ;
  rdfs:comment "Links RoleAssignment to AgentRole (the role assigned)." ;
  rdfs:domain :RoleAssignment ;
  rdfs:range :AgentRole .
:assignsRole rdf:type owl:FunctionalProperty .
:assignsRole owl:inverseOf :isAssignedRoleOf .
:isAssignedRoleOf rdf:type owl:ObjectProperty ;
  rdfs:label "is assigned role of" ;
  rdfs:comment "Links AgentRole to RoleAssignment as the assignment of that role." ;
