:compliesWithEN16931 rdf:type owl:FunctionalProperty .
:compliesWithEN16931 owl:inverseOf :isEN16931ComplianceFor .
:isEN16931ComplianceFor rdf:type owl:ObjectProperty ;
  rdfs:label "is EN16931 compliance for" ;
